-- Program member messages (Sammy, 06/10/2026): a two-week check-in and a
-- move-to-recurring offer a week before the 28 Day Program ends, driven by
-- the TeamUp sync. Both OFF until approved on the Program members screen.

insert into public.automations (id, name, summary, enabled, trigger, steps) values
  ('program_check_in', 'Program – two-week check-in', 'Two weeks into the 28 Day Program (from TeamUp), asks how it’s going. Off until approved on the Program members screen.', false, '{"type": "membership.started", "category": "Program Memberships"}'::jsonb, '[{"kind": "wait", "hours": 336}, {"kind": "email", "to": "contact", "subject": "Two weeks in, {first}: how’s it going?", "body": "Hi {first},\n\nYou’re halfway through the 28 Day Program. This is usually the point where it starts to feel normal, or where life gets in the way.\n\nEither way, a quick check-in: how many sessions have you managed so far, and is anything getting in the way? Reply to this email and one of the coaches will come back to you.\n\nThe second half is where the results show. See you in the gym.\n\n{team}"}]'::jsonb),
  ('program_ending', 'Program – a week to go, move to recurring', 'A week before the 28 Day Program ends (from TeamUp), offers a recurring membership. Off until approved on the Program members screen.', false, '{"type": "membership.ending", "daysBefore": 7, "category": "Program Memberships"}'::jsonb, '[{"kind": "email", "to": "contact", "subject": "Your 28 days are nearly up, {first}", "body": "Hi {first},\n\nYour 28 Day Program finishes in a week. Thank you for putting the work in.\n\nIf you’d like to carry on, you can move straight onto a recurring membership so there’s no gap: Premium for full access plus classes, Classes Only, or Facility Access Only if you’d rather train on your own. No joining fee, and you can cancel any time with 30 days’ notice.\n\nReply to this email or ask at the desk and we’ll set it up before your last session.\n\n{team}"}]'::jsonb)
on conflict (id) do nothing;
